package com.whaa.shop.cart.application;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.whaa.shop.cart.domain.CartItem;import com.whaa.shop.cart.infrastructure.CartItemMapper;import com.whaa.shop.common.exception.BusinessException;import com.whaa.shop.product.domain.*;import com.whaa.shop.product.infrastructure.*;import com.whaa.shop.promotion.application.PromotionService;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.util.*;
@Service public class CartService {private final CartItemMapper carts;private final SkuMapper skus;private final ProductMapper products;private final PromotionService promotions;public CartService(CartItemMapper c,SkuMapper s,ProductMapper p,PromotionService promotions){carts=c;skus=s;products=p;this.promotions=promotions;}
 @Transactional public void add(long uid,Long skuId,int quantity){if(quantity<1)throw new BusinessException("商品数量无效");Sku sku=skus.selectById(skuId);if(sku==null||!Boolean.TRUE.equals(sku.getEnabled())||sku.getStock()<quantity)throw new BusinessException("SKU不存在或库存不足");CartItem c=carts.selectOne(new LambdaQueryWrapper<CartItem>().eq(CartItem::getUserId,uid).eq(CartItem::getSkuId,skuId));if(c==null){c=new CartItem();c.setUserId(uid);c.setSkuId(skuId);c.setQuantity(quantity);c.setChecked(true);carts.insert(c);}else{int next=c.getQuantity()+quantity;if(next>sku.getStock())throw new BusinessException("库存不足");c.setQuantity(next);carts.updateById(c);}}
 public List<CartView> list(long uid){return carts.selectList(new LambdaQueryWrapper<CartItem>().eq(CartItem::getUserId,uid)).stream().map(c->{Sku s=skus.selectById(c.getSkuId());Product p=s==null?null:products.selectById(s.getProductId());return new CartView(c.getId(),c.getSkuId(),p==null?null:p.getId(),p==null?"商品已失效":p.getName(),p==null?null:p.getMainImage(),s==null?"":s.getSpecJson(),s==null?BigDecimal.ZERO:promotions.price(s.getId()).price(),c.getQuantity(),c.getChecked(),s==null?0:s.getStock());}).toList();}
 @Transactional public void update(long uid,Long id,int quantity,boolean checked){CartItem c=owned(uid,id);if(quantity<1)throw new BusinessException("数量至少为1");Sku s=skus.selectById(c.getSkuId());if(s==null||quantity>s.getStock())throw new BusinessException("库存不足");c.setQuantity(quantity);c.setChecked(checked);carts.updateById(c);}@Transactional public void delete(long uid,Long id){carts.deleteById(owned(uid,id));}public CartItem owned(long uid,Long id){CartItem c=carts.selectById(id);if(c==null||!c.getUserId().equals(uid))throw new BusinessException("购物车商品不存在");return c;}
 public record CartView(Long id,Long skuId,Long productId,String productName,String image,String spec,BigDecimal price,Integer quantity,Boolean checked,Integer stock){}
}
